/* Orthographic camera: rotation changes the view, never the source data. */
export function rotate3(point,yaw=35,pitch=20){const a=yaw*Math.PI/180,b=pitch*Math.PI/180,[x,y,z]=point,u=x*Math.cos(a)+z*Math.sin(a),w=-x*Math.sin(a)+z*Math.cos(a);return [u,y*Math.cos(b)-w*Math.sin(b),y*Math.sin(b)+w*Math.cos(b)];}
export function scene3(points,centers=[],camera={yaw:35,pitch:20,zoom:1}){const all=[...points,...centers];if(!all.length||all.some(p=>p.length!==3||p.some(x=>!Number.isFinite(x))))throw Error('3D requires three finite coordinates per point.');const lo=[0,1,2].map(j=>Math.min(...all.map(p=>p[j]))),hi=[0,1,2].map(j=>Math.max(...all.map(p=>p[j]))),mid=lo.map((v,j)=>(v+hi[j])/2),extent=Math.max(...hi.map((v,j)=>v-lo[j]))||1;const project=p=>{let r=rotate3(p.map((v,j)=>(v-mid[j])/extent),camera.yaw,camera.pitch);return [360+r[0]*290*camera.zoom,220-r[1]*290*camera.zoom,r[2]];};return {points:points.map(project),centers:centers.map(project),lo,hi,project};}
export function draw3(points,labels,centers,axis,names,camera,colors,esc,fmt,inspection={}){const s=scene3(points,centers,camera);const origin=s.lo,lines=axis.map((label,j)=>{let end=origin.slice();end[j]=s.hi[j];const a=s.project(origin),b=s.project(end);return `<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#60766d" stroke-width="1.5"/><text x="${b[0]+8}" y="${b[1]-9}" fill="#233c31" font-size="12">${['X','Y','Z'][j]}</text>`;}).join('');let dots=[...s.points.map((p,i)=>({p,i,center:false})),...s.centers.map((p,i)=>({p,i,center:true}))].sort((a,b)=>a.p[2]-b.p[2]);return `<svg id="plot3d" class="plot plot3d" viewBox="0 0 720 440" tabindex="0" role="img" aria-label="Rotatable 3D plot. Use arrow keys or rotation sliders. Cluster membership is available in the results table."><rect width="720" height="440" rx="10" fill="#f8fbf9"/>${lines}${dots.map(({p,i,center})=>center?`<g><rect x="${p[0]-11}" y="${p[1]-11}" width="22" height="22" rx="4" fill="${colors[i]}" stroke="white" stroke-width="2"/><text x="${p[0]}" y="${p[1]+4}" text-anchor="middle" fill="white" font-size="12">${i+1}</text></g>`:`<circle data-point="${i}" class="inspect-point ${inspection.selected===i?'selected-point':inspection.neighbors?.includes(i)?'neighbor-point':''}" cx="${p[0]}" cy="${p[1]}" r="${inspection.selected===i?9:inspection.neighbors?.includes(i)?7:5}" fill="${colors[labels[i]]}" opacity="${inspection.selected==null||inspection.selected===i||inspection.neighbors?.includes(i)?1:.22}"><title>${esc(names[i])} · Cluster ${labels[i]+1} · ${points[i].map(fmt).join(', ')}</title></circle>`).join('')}</svg><div class="axis-key">${axis.map((a,j)=>`<span><strong>${['X','Y','Z'][j]}</strong> ${esc(a)}<br><small>${fmt(s.lo[j])} to ${fmt(s.hi[j])}</small></span>`).join('')}</div>`;}
